    void test13LossesOfAvailableRoomIsTheMaxPriceInList() {
        shouldFail(() -> {
            Room room;

            room = new Room();

            assertEquals(maxPriceInList(), room.lossUsingIfAbsentGuestType(defaultPriceList(), () -> fail()));
        });
    }

